import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S03/S03E08.html","title":"S03E08 The One with the Giant Poking Device","lang":"zh-CN","frontmatter":{"title":"S03E08 The One with the Giant Poking Device","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":56},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":31.93,"words":9578},"filePathRelative":"语言/英语/Friends老友记/S03/S03E08.md"}`),l={name:`S03E08.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-with-the-giant-poking-device" tabindex="-1"><a class="header-anchor" href="#the-one-with-the-giant-poking-device"><span>The One with the Giant Poking Device</span></a></h1><blockquote><p><em>带巨型拨动装置的那个</em></p></blockquote><p>The One With The Giant Poking Device</p><blockquote><p>那个有巨大刺穿装置的</p></blockquote><p><strong>Written by: Adam Chase</strong></p><blockquote><p>作者：亚当·蔡斯</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Phoebe, Chandler, and Ross are there, Rachel is serving brownies.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，菲比，钱德勒和罗斯在那里，瑞秋在供应巧克力饼。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S03/S03E08/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`Rachel Green:`,-1),c[3]||=i(` Here you go Pheebs. Who else wants one of my special homemade brownies?`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`给你，菲比。还有谁想要我特制的布朗尼？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/002.mp3`}),c[5]||=i(),c[6]||=a(`strong`,null,`Chandler Bing:`,-1),c[7]||=i(` I will have one. (Ross and him both take one.)`,-1),c[8]||=a(`blockquote`,null,[a(`p`,null,`我要一个。（罗斯和他都拿了一个。）`)],-1),c[9]||=a(`p`,null,[a(`em`,null,`(Phoebe takes a bite and spits it out and screams.)`)],-1),c[10]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（菲比咬了一口，吐了出来，尖叫起来。）`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/003.mp3`}),c[11]||=i(),c[12]||=a(`strong`,null,`Chandler Bing:`,-1),c[13]||=i(` Okay, I’m not gonna have one.`,-1),c[14]||=a(`blockquote`,null,[a(`p`,null,`好吧，我不会要的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/004.mp3`}),c[15]||=i(),c[16]||=a(`strong`,null,`Ross Geller:`,-1),c[17]||=i(` Neither will I. (they both put back the brownies.)`,-1),c[18]||=a(`blockquote`,null,[a(`p`,null,`我也不会。（他们都把布朗尼放回去了。）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/005.mp3`}),c[19]||=i(),c[20]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[21]||=i(` No, no, it’s just my tooth.`,-1),c[22]||=a(`blockquote`,null,[a(`p`,null,`不，不，只是我的牙齿。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/006.mp3`}),c[23]||=i(),c[24]||=a(`strong`,null,`Chandler Bing:`,-1),c[25]||=i(` All right I’ll have one. (he and Ross take another brownie,)`,-1),c[26]||=a(`blockquote`,null,[a(`p`,null,`好吧，我要一个。（他和罗斯又吃了一块布朗尼）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/007.mp3`}),c[27]||=i(),c[28]||=a(`strong`,null,`Ross Geller:`,-1),c[29]||=i(` So what’s a matter, you need a dentist? I’ve got a good one.`,-1),c[30]||=a(`blockquote`,null,[a(`p`,null,`怎么了，你需要一个牙医？我有一个好的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/008.mp3`}),c[31]||=i(),c[32]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[33]||=i(` No thanks, I have a good one too. I just, I, I can’t see him.`,-1),c[34]||=a(`blockquote`,null,[a(`p`,null,`不用了，谢谢，我也有一个好的。我只是，我，我看不见他。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/009.mp3`}),c[35]||=i(),c[36]||=a(`strong`,null,`Chandler Bing:`,-1),c[37]||=i(` See that is the problem with invisible dentists.`,-1),c[38]||=a(`blockquote`,null,[a(`p`,null,`看，这就是隐形牙医的问题。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/010.mp3`}),c[39]||=i(),c[40]||=a(`strong`,null,`Ross Geller:`,-1),c[41]||=i(` Why? Why can’t you go to him?`,-1),c[42]||=a(`blockquote`,null,[a(`p`,null,`为什么？你为什么不能去找他？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/011.mp3`}),c[43]||=i(),c[44]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[45]||=i(` Because, every time I go to the dentist, somebody dies.`,-1),c[46]||=a(`blockquote`,null,[a(`p`,null,`因为，每次我去看牙医，都会有人死。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/012.mp3`}),c[47]||=i(),c[48]||=a(`strong`,null,`Chandler Bing:`,-1),c[49]||=i(` That is so weird, because every time I go to the dentist, I look down the hygienist’s blouse.`,-1),c[50]||=a(`blockquote`,null,[a(`p`,null,`那太奇怪了，因为每次我去看牙医，我都会看不起卫生员的衬衫。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/013.mp3`}),c[51]||=i(),c[52]||=a(`strong`,null,`Rachel Green:`,-1),c[53]||=i(` Phoebe, what? Umm...what?!`,-1),c[54]||=a(`blockquote`,null,[a(`p`,null,`菲比，什么？嗯…什么？！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/014.mp3`}),c[55]||=i(),c[56]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[57]||=i(` Yeah, yeah, first there was my aunt Mary, and then there was umm, John, my mailman, and then my, my cowboy friend ‘Albino Bob’.`,-1),c[58]||=a(`blockquote`,null,[a(`p`,null,`是的，是的，首先是我的玛丽阿姨，然后是嗯，约翰，我的邮递员，然后是我的，我的牛仔朋友“白化病鲍勃”。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/015.mp3`}),c[59]||=i(),c[60]||=a(`strong`,null,`Rachel Green:`,-1),c[61]||=i(` And all these people actually died?`,-1),c[62]||=a(`blockquote`,null,[a(`p`,null,`所有这些人都死了？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/016.mp3`}),c[63]||=i(),c[64]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[65]||=i(` Yes, while I was in the chair! That’s why I take such good care of my teeth now, y'know, it’s not about oral hygiene, I floss to save lives!`,-1),c[66]||=a(`blockquote`,null,[a(`p`,null,`是的，当我坐在椅子上的时候！这就是为什么我现在要好好保养我的牙齿，你知道，这不是关于口腔卫生，我用牙线来拯救生命！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/017.mp3`}),c[67]||=i(),c[68]||=a(`strong`,null,`Ross Geller:`,-1),c[69]||=i(` Pheebs, come on, you didn’t kill anybody, these people just happened to die when you went to the dentist. It’s, it’s, it’s just ah, a coincidence.`,-1),c[70]||=a(`blockquote`,null,[a(`p`,null,`菲比，拜托，你没有杀人，这些人只是在你去看牙医的时候碰巧死了。这，这，这只是巧合。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/018.mp3`}),c[71]||=t(` <strong>Phoebe Buffay:</strong> Well tell that to them. Oh! You can’t, their dead.<blockquote><p>那就告诉他们吧。哦你不能，他们死了。</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Central Perk, Ross, Rachel, and Phoebe are there.</em></p><blockquote><p>🎬 <em>中央公园，罗斯，瑞秋和菲比在那里</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S03/S03E08/019.mp3`}),c[72]||=i(),c[73]||=a(`strong`,null,`Ross Geller:`,-1),c[74]||=i(` Thanks, Gunther. (takes the plate Gunther serves him and Rachel comes up and kisses him) (to Rachel) Hey! (to Gunther) Umm, can I get a napkin too?`,-1),c[75]||=a(`blockquote`,null,[a(`p`,null,`谢谢，冈瑟。（拿着冈瑟端来的盘子，瑞秋走过来亲吻他）（对瑞秋）嘿！（对冈瑟）嗯，我也能要一张餐巾吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/020.mp3`}),c[76]||=i(),c[77]||=a(`strong`,null,`Gunther:`,-1),c[78]||=i(` Oh, like you don’t already have everything.`,-1),c[79]||=a(`blockquote`,null,[a(`p`,null,`哦，好像你还没有拥有一切。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/021.mp3`}),c[80]||=i(),c[81]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[82]||=i(` (trying to bite into an apple) Ow! Ow! (drops the apple in disgust.)`,-1),c[83]||=a(`blockquote`,null,[a(`p`,null,`（试图咬苹果）哇！噢（厌恶地扔下苹果。）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/022.mp3`}),c[84]||=i(),c[85]||=a(`strong`,null,`Rachel Green:`,-1),c[86]||=i(` Phoebe, your in pain, would you just go to the dentist, just go.`,-1),c[87]||=a(`blockquote`,null,[a(`p`,null,`菲比，你的疼痛，你能去看牙医吗，去吧。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/023.mp3`}),c[88]||=i(),c[89]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[90]||=i(` All right, fine, fine, but if you’re my next victim, don’t come back as a poltergeist and like suck me into the TV set.`,-1),c[91]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，好吧，但如果你是我的下一个受害者，别再像恶作剧一样把我拖进电视机里。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/024.mp3`}),c[92]||=i(),c[93]||=a(`strong`,null,`Rachel Green:`,-1),c[94]||=i(` I promise.`,-1),c[95]||=a(`blockquote`,null,[a(`p`,null,`我保证。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/025.mp3`}),c[96]||=i(),c[97]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[98]||=i(` Although, don’t feel like you can’t visit.`,-1),c[99]||=a(`blockquote`,null,[a(`p`,null,`不过，别觉得你不能来。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/026.mp3`}),c[100]||=i(),c[101]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[102]||=i(` (entering with Monica) Hey, is, is, is Chandler here?`,-1),c[103]||=a(`blockquote`,null,[a(`p`,null,`（和莫妮卡一起进来）嘿，钱德勒在吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/027.mp3`}),c[104]||=i(),c[105]||=a(`strong`,null,`Ross Geller:`,-1),c[106]||=i(` (patting his clothes like he is looking for his wallet) No, no he’s not.`,-1),c[107]||=a(`blockquote`,null,[a(`p`,null,`（拍着他的衣服，好像在找钱包）不，不，他不是。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/028.mp3`}),c[108]||=i(),c[109]||=a(`strong`,null,`Monica Geller:`,-1),c[110]||=i(` You guys, Joey just saw Janice kissing her ex-husband.`,-1),c[111]||=a(`blockquote`,null,[a(`p`,null,`你们这些家伙，乔伊刚刚看到珍妮丝亲吻她的前夫。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/029.mp3`}),c[112]||=i(),c[113]||=a(`strong`,null,`Ross Geller:`,-1),c[114]||=i(` What? (to Joey) So what are you going to do? I mean how, how are you going to tell Chandler?`,-1),c[115]||=a(`blockquote`,null,[a(`p`,null,`什么？（对乔伊）那你打算怎么办？我是说你打算怎么告诉钱德勒？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/030.mp3`}),c[116]||=i(),c[117]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[118]||=i(` Well, I was thinking about that and I, I think the best way would be, to not.`,-1),c[119]||=a(`blockquote`,null,[a(`p`,null,`嗯，我在想，我，我想最好的办法是，不要。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/031.mp3`}),c[120]||=i(),c[121]||=a(`strong`,null,`Rachel Green:`,-1),c[122]||=i(` Joey, you can’t keep this to yourself, if you know about this, you have to tell him.`,-1),c[123]||=a(`blockquote`,null,[a(`p`,null,`乔伊，你不能对自己隐瞒，如果你知道这件事，你必须告诉他。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/032.mp3`}),c[124]||=i(),c[125]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[126]||=i(` It’ll kill him. I mean it’ll, it’ll just kill him.`,-1),c[127]||=a(`blockquote`,null,[a(`p`,null,`那会杀了他的。我的意思是，它会，它会杀了他。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/033.mp3`}),c[128]||=i(),c[129]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[130]||=i(` Well, you could wait ‘til I go to the dentist, maybe I’ll kill him.`,-1),c[131]||=a(`blockquote`,null,[a(`p`,null,`嗯，你可以等我去看牙医，也许我会杀了他。`)],-1),c[132]||=a(`hr`,null,null,-1),c[133]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, All are there except for Chandler.`)],-1),c[134]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，除了钱德勒都在那里。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/034.mp3`}),c[135]||=i(),c[136]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[137]||=i(` (looking out the window) Ewww! Ugly Naked Guy is using his new hammock. It’s like a Play-Doo Fat Factory.`,-1),c[138]||=a(`blockquote`,null,[a(`p`,null,`（看着窗外）哇！丑陋的裸男正在使用他的新吊床。这就像一个玩具工厂。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/035.mp3`}),c[139]||=i(),c[140]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[141]||=i(` Well, I’m going to the dentist, so listen, okay, just be on the look out for anything that, that, that you can fall into, or, or that can fall on you, or... All right, just look out! Okay, And um, I also just wanna, I just wanna tell you all that um...... (starts to cry and runs out)`,-1),c[142]||=a(`blockquote`,null,[a(`p`,null,`嗯，我要去看牙医，所以听着，好吧，小心你可能会掉进去的东西，或者，或者可能会掉到你身上的东西，或者。。。好吧，小心！好的，嗯，我也只是想，我只是想告诉你所有这些嗯。。。。。。（哭了起来，跑了出去）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/036.mp3`}),c[143]||=i(),c[144]||=a(`strong`,null,`Ross Geller:`,-1),c[145]||=i(` Okay, I have a problem I have to go into work for a few hours, some kids messed up the Homo Sapien display.`,-1),c[146]||=a(`blockquote`,null,[a(`p`,null,`好吧，我有个问题，我得工作几个小时，有些孩子把智人的展示搞砸了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/037.mp3`}),c[147]||=i(),c[148]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[149]||=i(` What did they do?`,-1),c[150]||=a(`blockquote`,null,[a(`p`,null,`他们做了什么？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/038.mp3`}),c[151]||=i(),c[152]||=a(`strong`,null,`Ross Geller:`,-1),c[153]||=i(` Well, they painted over the word ‘Sapien’ for one thing, then they rearranged the figures, let’s just leave it at that.`,-1),c[154]||=a(`blockquote`,null,[a(`p`,null,`嗯，他们画了一个单词‘Sapien’，然后重新排列了数字，就这样吧。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/039.mp3`}),c[155]||=i(),c[156]||=a(`strong`,null,`Monica Geller:`,-1),c[157]||=i(` So, do you want me to watch Ben for you?`,-1),c[158]||=a(`blockquote`,null,[a(`p`,null,`那么，你想让我帮你照看本吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/040.mp3`}),c[159]||=i(),c[160]||=a(`strong`,null,`Ross Geller:`,-1),c[161]||=i(` Yes, that’s what I was going to ask, thank you.`,-1),c[162]||=a(`blockquote`,null,[a(`p`,null,`是的，这就是我要问的，谢谢。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/041.mp3`}),c[163]||=i(),c[164]||=a(`strong`,null,`Rachel Green:`,-1),c[165]||=i(` Whoa! Wait! Hello! What about me?`,-1),c[166]||=a(`blockquote`,null,[a(`p`,null,`哇！等待你好我呢？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/042.mp3`}),c[167]||=i(),c[168]||=a(`strong`,null,`Ross Geller:`,-1),c[169]||=i(` You? You! Want to watch Ben? (in the background Monica mouths ‘Don’t worry, I’ll be here the whole time.’ to Ross.) Yes! That’d be great, no, I just wanted to ask Monica, because I know how empty her life is. (Monica sarcastically mouths ‘Yeah!’ and holds up her thumb.)`,-1),c[170]||=a(`blockquote`,null,[a(`p`,null,`你呢？你！想看本吗？（背景中莫妮卡·默斯对罗斯说：“别担心，我会一直在这里的。”是的！那太好了，不，我只是想问问莫妮卡，因为我知道她的生活是多么空虚。（莫妮卡讽刺地说：“是啊！”然后举起拇指。）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/043.mp3`}),c[171]||=i(),c[172]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[173]||=i(` Hey-hey, Ross?`,-1),c[174]||=a(`blockquote`,null,[a(`p`,null,`嘿，罗斯？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/044.mp3`}),c[175]||=i(),c[176]||=a(`strong`,null,`Ross Geller:`,-1),c[177]||=i(` Yeah.`,-1),c[178]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/045.mp3`}),c[179]||=i(),c[180]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[181]||=i(` I’ve got a science question.`,-1),c[182]||=a(`blockquote`,null,[a(`p`,null,`我有一个科学问题。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/046.mp3`}),c[183]||=i(),c[184]||=a(`strong`,null,`Ross Geller:`,-1),c[185]||=i(` Hmm?`,-1),c[186]||=a(`blockquote`,null,[a(`p`,null,`嗯？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/047.mp3`}),c[187]||=i(),c[188]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[189]||=i(` If the Homo Sapiens, were in fact ‘Homo-sapien’, is that why there extinct?`,-1),c[190]||=a(`blockquote`,null,[a(`p`,null,`如果智人实际上是“智人”，这就是为什么会有灭绝的物种吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/048.mp3`}),c[191]||=i(),c[192]||=a(`strong`,null,`Ross Geller:`,-1),c[193]||=i(` Joey, Homo Sapiens are people.`,-1),c[194]||=a(`blockquote`,null,[a(`p`,null,`乔伊，智人是人。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/049.mp3`}),c[195]||=i(),c[196]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[197]||=i(` Hey-hey, I’m not judging.`,-1),c[198]||=a(`blockquote`,null,[a(`p`,null,`嘿，嘿，我不是在评判。`)],-1),c[199]||=a(`hr`,null,null,-1),c[200]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Monica and Rachel are babysitting Ben.`)],-1),c[201]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，莫妮卡和瑞秋在照顾本。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/050.mp3`}),c[202]||=i(),c[203]||=a(`strong`,null,`Rachel Green:`,-1),c[204]||=i(` (holding Ben) Look Benny, spoon. (moves it back and forth) Spoon. Come on! All right, y'know what I think he’s bored.`,-1),c[205]||=a(`blockquote`,null,[a(`p`,null,`（抱着本）看本尼，斯彭。（来回移动）勺子。来吧好吧，你知道我觉得他很无聊。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/051.mp3`}),c[206]||=i(),c[207]||=a(`strong`,null,`Monica Geller:`,-1),c[208]||=i(` Here. Ben, do you wanna play the airplane game, do you wanna show Rachel? Come here. (takes Ben) We’re gonna do something fun. Okay. (throws Ben up in the air a little bit and catches him) Weee!! (moves into the living room and does it again) Weee!! (starts to walk back into the kitchen as she does it again, and hits Ben’s head on that wooden beam across the ceiling.)`,-1),c[209]||=a(`blockquote`,null,[a(`p`,null,`给。本，你想玩飞机游戏吗，你想让瑞秋看看吗？过来。（带着本）我们要做些有趣的事。可以（将本抛向空中一点，然后抓住他）Weee！！（搬进客厅又做了一次）Weee！！（当她再次走进厨房时，她开始走回厨房，并将本的头撞在天花板上的木梁上。）`)],-1),c[210]||=a(`p`,null,`[cut to later]`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`[切换到稍后]`)],-1),r(p,{src:`/audio/friends/S03/S03E08/052.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`Monica Geller:`,-1),c[214]||=i(` (to Ben) Who’s so brave, you’re so brave, yes you are, you’re so brave.`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`（对本）谁这么勇敢，你这么勇敢，是的，你这么勇敢。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/053.mp3`}),c[216]||=i(),c[217]||=a(`strong`,null,`Rachel Green:`,-1),c[218]||=i(` Okay. Okay honey, he’s fine, he’s fine, let’s just put him down. Come here, Ben. (sets him on the couch) See that’s a good boy. (to Monica) How could you do that to him!! Ross trusted me, what is he going to say?!`,-1),c[219]||=a(`blockquote`,null,[a(`p`,null,`好的。好了，亲爱的，他很好，他很好，我们把他放下。过来，本。（把他放在沙发上）看，那是个好孩子。（对莫妮卡）你怎么能这样对他！！罗斯信任我，他会说什么？！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/054.mp3`}),c[220]||=i(),c[221]||=a(`strong`,null,`Monica Geller:`,-1),c[222]||=i(` He’s not gonna say anything, because we’re not gonna tell him.`,-1),c[223]||=a(`blockquote`,null,[a(`p`,null,`他什么也不会说，因为我们不会告诉他。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/055.mp3`}),c[224]||=i(),c[225]||=a(`strong`,null,`Rachel Green:`,-1),c[226]||=i(` We’re not?!`,-1),c[227]||=a(`blockquote`,null,[a(`p`,null,`我们不是？！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/056.mp3`}),c[228]||=i(),c[229]||=a(`strong`,null,`Monica Geller:`,-1),c[230]||=i(` No we’re not.`,-1),c[231]||=a(`blockquote`,null,[a(`p`,null,`不，我们不是。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/057.mp3`}),c[232]||=i(),c[233]||=a(`strong`,null,`Rachel Green:`,-1),c[234]||=i(` All right, I like that.`,-1),c[235]||=a(`blockquote`,null,[a(`p`,null,`好吧，我喜欢。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/058.mp3`}),c[236]||=i(),c[237]||=a(`strong`,null,`Monica Geller:`,-1),c[238]||=i(` Okay.`,-1),c[239]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/059.mp3`}),c[240]||=i(),c[241]||=a(`strong`,null,`Rachel Green:`,-1),c[242]||=i(` So we’re okay, we’re okay, we’re okay, (starts to exam Ben) aren’t we? No, we’re not okay, we’re not okay, there’s a bump, there’s a bump.`,-1),c[243]||=a(`blockquote`,null,[a(`p`,null,`所以我们没事，我们没事，我们没事，（开始考本）不是吗？不，我们不好，我们不好，有个肿块，有个肿块。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/060.mp3`}),c[244]||=i(),c[245]||=a(`strong`,null,`Monica Geller:`,-1),c[246]||=i(` Oh my God! Well push it in! Push it in!`,-1),c[247]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！好吧，把它推进去！把它推进去！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/061.mp3`}),c[248]||=i(),c[249]||=a(`strong`,null,`Rachel Green:`,-1),c[250]||=i(` I cannot push it in!`,-1),c[251]||=a(`blockquote`,null,[a(`p`,null,`我不能把它推进去！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/062.mp3`}),c[252]||=i(),c[253]||=a(`strong`,null,`Monica Geller:`,-1),c[254]||=i(` Okay, we’re gonna need a distraction.`,-1),c[255]||=a(`blockquote`,null,[a(`p`,null,`好吧，我们需要分散一下注意力。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/063.mp3`}),c[256]||=i(),c[257]||=a(`strong`,null,`Rachel Green:`,-1),c[258]||=i(` Okay, okay, okay.`,-1),c[259]||=a(`blockquote`,null,[a(`p`,null,`好的，好的，好的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/064.mp3`}),c[260]||=i(),c[261]||=a(`strong`,null,`Monica Geller:`,-1),c[262]||=i(` I got it!`,-1),c[263]||=a(`blockquote`,null,[a(`p`,null,`我明白了！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/065.mp3`}),c[264]||=i(),c[265]||=a(`strong`,null,`Rachel Green:`,-1),c[266]||=i(` Okay.`,-1),c[267]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/066.mp3`}),c[268]||=i(),c[269]||=a(`strong`,null,`Monica Geller:`,-1),c[270]||=i(` The second that Ross walks in that door, I want you take him back to your bedroom and do whatever it is that you do that makes him go, (high pitched) rweee!!`,-1),c[271]||=a(`blockquote`,null,[a(`p`,null,`罗斯走进那扇门的那一刻，我要你把他带回你的卧室，做任何能让他走的事，（高音）RWEE！！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/067.mp3`}),c[272]||=i(),c[273]||=a(`strong`,null,`Rachel Green:`,-1),c[274]||=i(` Or. We could put a hat on his head.`,-1),c[275]||=a(`blockquote`,null,[a(`p`,null,`或者。我们可以把帽子戴在他的头上。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/068.mp3`}),c[276]||=i(),c[277]||=a(`strong`,null,`Monica Geller:`,-1),c[278]||=i(` A hat! Yes! We need a hat.`,-1),c[279]||=a(`blockquote`,null,[a(`p`,null,`帽子！对我们需要一顶帽子。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/069.mp3`}),c[280]||=i(),c[281]||=a(`strong`,null,`Rachel Green:`,-1),c[282]||=i(` We need a hat..`,-1),c[283]||=a(`blockquote`,null,[a(`p`,null,`我们需要一顶帽子。。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/070.mp3`}),c[284]||=i(),c[285]||=a(`strong`,null,`Monica Geller:`,-1),c[286]||=i(` Where are we gonna find a tiny little hat?`,-1),c[287]||=a(`blockquote`,null,[a(`p`,null,`我们在哪里能找到一顶小帽子？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/071.mp3`}),c[288]||=i(),c[289]||=a(`strong`,null,`Rachel Green:`,-1),c[290]||=i(` Oh, oh, oh, I’ll get ‘Rainy Day Bear’!! (runs to get him)`,-1),c[291]||=a(`blockquote`,null,[a(`p`,null,`哦，哦，哦，哦，我要买“雨天熊”！！（跑着去找他）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/072.mp3`}),c[292]||=i(),c[293]||=a(`strong`,null,`Monica Geller:`,-1),c[294]||=i(` Because he’ll know what to do? (Rachel comes out of her room with a bear that’s dressed in a rain suit.) Oh my God, you’re a genius!`,-1),c[295]||=a(`blockquote`,null,[a(`p`,null,`因为他会知道该怎么做？（瑞秋带着一只穿着雨衣的熊走出房间。）哦，天哪，你真是个天才！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/073.mp3`}),c[296]||=i(),c[297]||=a(`strong`,null,`Rachel Green:`,-1),c[298]||=i(` Oh God, oh God, it’s sowed on though.`,-1),c[299]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，哦，天哪，这是种在你身上的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/074.mp3`}),c[300]||=i(),c[301]||=a(`strong`,null,`Monica Geller:`,-1),c[302]||=i(` Give it. Give it.`,-1),c[303]||=a(`blockquote`,null,[a(`p`,null,`给我。给我。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/075.mp3`}),c[304]||=t(` <strong>Rachel Green:</strong> Okay.<blockquote><p>好的。</p></blockquote><p><em>(Monica takes the bear, grabs his hat, and rips off his head.)</em></p><blockquote><p><em>（莫妮卡抓住熊，抓起他的帽子，扯下他的头。）</em></p></blockquote><p>Monica and **Rachel Green: **Oh!!</p><blockquote><p>莫妮卡和<strong>瑞秋·格林：</strong>哦！！</p></blockquote>`,8),r(p,{src:`/audio/friends/S03/S03E08/076.mp3`}),c[305]||=i(),c[306]||=a(`strong`,null,`Rachel Green:`,-1),c[307]||=i(` Oh, it’s just like a bloodbath in here today.`,-1),c[308]||=a(`blockquote`,null,[a(`p`,null,`哦，今天这里就像一场大屠杀。`)],-1),c[309]||=a(`hr`,null,null,-1),c[310]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The street, Chandler and Joey are walking past a jewelery store.`)],-1),c[311]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`街上，钱德勒和乔伊走过一家珠宝店。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/077.mp3`}),c[312]||=i(),c[313]||=a(`strong`,null,`Chandler Bing:`,-1),c[314]||=i(` Hey! Hold on a minute, hold on a second. Do you think these pearls are nice?`,-1),c[315]||=a(`blockquote`,null,[a(`p`,null,`嘿！等一下，等一下。你觉得这些珍珠好看吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/078.mp3`}),c[316]||=i(),c[317]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[318]||=i(` I’d really prefer a mountain bike.`,-1),c[319]||=a(`blockquote`,null,[a(`p`,null,`我更喜欢山地车。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/079.mp3`}),c[320]||=i(),c[321]||=a(`strong`,null,`Chandler Bing:`,-1),c[322]||=i(` Janice’s birthday is coming up, I want to get her something speacial. Come in here with me.`,-1),c[323]||=a(`blockquote`,null,[a(`p`,null,`珍妮丝的生日快到了，我想给她买点特别的东西。跟我进来。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/080.mp3`}),c[324]||=i(),c[325]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[326]||=i(` Whoa, whoa, whoa, wait, whoa. Do you ah, want to get her something speacial, get her flowers, get her candy, get her gum, girls love gum.`,-1),c[327]||=a(`blockquote`,null,[a(`p`,null,`哇，哇，哇，等等，哇。你想给她买些特别的东西吗，给她买些花，给她买些糖果，给她买口香糖，女孩们都喜欢口香糖。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/081.mp3`}),c[328]||=i(),c[329]||=a(`strong`,null,`Chandler Bing:`,-1),c[330]||=i(` That’s a good idea, ‘Dear Janice have a Hubba-Bubba birthday’. I would like to get her something serious.`,-1),c[331]||=a(`blockquote`,null,[a(`p`,null,`这是个好主意，‘亲爱的珍妮丝，祝你生日快乐’。我想给她弄点正经事。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/082.mp3`}),c[332]||=i(),c[333]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[334]||=i(` Oh, you want something serious. Y'know what you should do, you should get her one of those um, barium enemas. Those are dead serious.`,-1),c[335]||=a(`blockquote`,null,[a(`p`,null,`哦，你想要点正经事。你知道你应该怎么做，你应该给她做一个钡灌肠。那些都很严重。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/083.mp3`}),c[336]||=i(),c[337]||=a(`strong`,null,`Chandler Bing:`,-1),c[338]||=i(` All right. Look, I’m gonna go in here, and you don’t buy me anything ever. (starts to go into the store)`,-1),c[339]||=a(`blockquote`,null,[a(`p`,null,`好吧。听着，我要进去了，你永远不会给我买任何东西。（开始走进商店）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/084.mp3`}),c[340]||=i(),c[341]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[342]||=i(` (stopping him) No, no, you can’t, you can’t, okay, you can’t, you can’t buy her pearls, you just can’t, you can’t, you can’t.`,-1),c[343]||=a(`blockquote`,null,[a(`p`,null,`不，不，你不能，你不能，好吧，你不能，你不能买她的珍珠，你就是不能，你不能，你不能。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/085.mp3`}),c[344]||=i(),c[345]||=a(`strong`,null,`Chandler Bing:`,-1),c[346]||=i(` Why not?!`,-1),c[347]||=a(`blockquote`,null,[a(`p`,null,`为什么不呢？！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/086.mp3`}),c[348]||=i(),c[349]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[350]||=i(` Oh God. Uh, okay, here’s the thing, this is the thing, okay, the thing is...`,-1),c[351]||=a(`blockquote`,null,[a(`p`,null,`哦，天啊。嗯，好吧，事情是这样的，事情是这样的，好吧，事情是。。。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/087.mp3`}),c[352]||=i(),c[353]||=a(`strong`,null,`Chandler Bing:`,-1),c[354]||=i(` What is the thing?`,-1),c[355]||=a(`blockquote`,null,[a(`p`,null,`什么事？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/088.mp3`}),c[356]||=i(),c[357]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[358]||=i(` Okay. I went down to the ‘Mattress King’ showroom and, and I saw Janice, kissing her ex-husband.`,-1),c[359]||=a(`blockquote`,null,[a(`p`,null,`好的。我去了“床垫王”陈列室，看到珍妮丝在亲吻她的前夫。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/089.mp3`}),c[360]||=i(),c[361]||=a(`strong`,null,`Chandler Bing:`,-1),c[362]||=i(` (shocked) What?`,-1),c[363]||=a(`blockquote`,null,[a(`p`,null,`（震惊）什么？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/090.mp3`}),c[364]||=i(),c[365]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[366]||=i(` They were in his office.`,-1),c[367]||=a(`blockquote`,null,[a(`p`,null,`他们在他的办公室里。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/091.mp3`}),c[368]||=i(),c[369]||=a(`strong`,null,`Chandler Bing:`,-1),c[370]||=i(` Well she, she wouldn’t do that, she’s with, she’s with me.`,-1),c[371]||=a(`blockquote`,null,[a(`p`,null,`她不会那么做的，她和我在一起。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/092.mp3`}),c[372]||=i(),c[373]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[374]||=i(` I’m telling you man, I saw it.`,-1),c[375]||=a(`blockquote`,null,[a(`p`,null,`我告诉你，伙计，我看到了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/093.mp3`}),c[376]||=i(),c[377]||=a(`strong`,null,`Chandler Bing:`,-1),c[378]||=i(` Yeah, well, you’re wrong! Okay, you’re wrong.`,-1),c[379]||=a(`blockquote`,null,[a(`p`,null,`是啊，你错了！好吧，你错了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/094.mp3`}),c[380]||=i(),c[381]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[382]||=i(` I’m not wrong! I wish I was. I’m sorry. Bet that barium enema doesn’t sound so bad now, huh?`,-1),c[383]||=a(`blockquote`,null,[a(`p`,null,`我没有错！我希望我是。我很抱歉。我打赌钡灌肠现在听起来没那么糟糕吧？`)],-1),c[384]||=a(`hr`,null,null,-1),c[385]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Monica and Rachel are dressing up Ben in the entire rain suit from Rainy Day Bear.`)],-1),c[386]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，莫妮卡和瑞秋穿着雨天熊的雨衣打扮本。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/095.mp3`}),c[387]||=i(),c[388]||=a(`strong`,null,`Monica Geller:`,-1),c[389]||=i(` It just makes more sense as an ensemble.`,-1),c[390]||=a(`blockquote`,null,[a(`p`,null,`它只是作为一个合奏更有意义。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/096.mp3`}),c[391]||=i(),c[392]||=a(`strong`,null,`Rachel Green:`,-1),c[393]||=i(` Right.`,-1),c[394]||=a(`blockquote`,null,[a(`p`,null,`对。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/097.mp3`}),c[395]||=i(),c[396]||=a(`strong`,null,`Monica Geller:`,-1),c[397]||=i(` Besides, it takes the focus off the hat.`,-1),c[398]||=a(`blockquote`,null,[a(`p`,null,`此外，这会让你的注意力从帽子上移开。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/098.mp3`}),c[399]||=i(),c[400]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[401]||=i(` (running through the door) No! Oh! You’re alive! You’re alive!`,-1),c[402]||=a(`blockquote`,null,[a(`p`,null,`（跑进门）不！哦你还活着！你还活着！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/099.mp3`}),c[403]||=i(),c[404]||=a(`strong`,null,`Rachel Green:`,-1),c[405]||=i(` See Pheebs, I promised you no one would die, didn’t I?`,-1),c[406]||=a(`blockquote`,null,[a(`p`,null,`看，菲比，我答应过你没有人会死，不是吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/100.mp3`}),c[407]||=i(),c[408]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[409]||=i(` Yeah, well, we’ll see about that. Can I use your phone? I just wanna call everyone I know.`,-1),c[410]||=a(`blockquote`,null,[a(`p`,null,`是的，好吧，我们等着瞧。我能用一下你的电话吗？我只想给我认识的每个人打电话。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/101.mp3`}),c[411]||=i(),c[412]||=a(`strong`,null,`Monica Geller:`,-1),c[413]||=i(` Sure, we have no money, go ahead.`,-1),c[414]||=a(`blockquote`,null,[a(`p`,null,`当然，我们没有钱，去吧。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/102.mp3`}),c[415]||=i(),c[416]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[417]||=i(` (on phone) ‘Hey! You’re not dead! Okay, see ya!’`,-1),c[418]||=a(`blockquote`,null,[a(`p`,null,`（在电话里）“嘿！你还没死！好的，再见`)],-1),r(p,{src:`/audio/friends/S03/S03E08/103.mp3`}),c[419]||=i(),c[420]||=a(`strong`,null,`Ben:`,-1),c[421]||=i(` Monica.`,-1),c[422]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/104.mp3`}),c[423]||=i(),c[424]||=a(`strong`,null,`Monica Geller:`,-1),c[425]||=i(` Oh my God! He just said my name! Did you hear that?`,-1),c[426]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！他刚说了我的名字！你听到了吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/105.mp3`}),c[427]||=i(),c[428]||=a(`strong`,null,`Ben:`,-1),c[429]||=i(` Monica bang!`,-1),c[430]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡·邦！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/106.mp3`}),c[431]||=i(),c[432]||=a(`strong`,null,`Rachel Green:`,-1),c[433]||=i(` Okay, I heard that.`,-1),c[434]||=a(`blockquote`,null,[a(`p`,null,`好的，我听说了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/107.mp3`}),c[435]||=i(),c[436]||=a(`strong`,null,`Monica Geller:`,-1),c[437]||=i(` Did he just say ‘Monica bang’?`,-1),c[438]||=a(`blockquote`,null,[a(`p`,null,`他刚才是说“莫妮卡·邦”吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/108.mp3`}),c[439]||=i(),c[440]||=a(`strong`,null,`Rachel Green:`,-1),c[441]||=i(` Uh-huh.`,-1),c[442]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/109.mp3`}),c[443]||=i(),c[444]||=a(`strong`,null,`Monica Geller:`,-1),c[445]||=i(` Oh my God! He’s gonna rat me out!`,-1),c[446]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！他会揭发我的！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/110.mp3`}),c[447]||=i(),c[448]||=a(`strong`,null,`Ben:`,-1),c[449]||=i(` Monica bang!`,-1),c[450]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡·邦！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/111.mp3`}),c[451]||=i(),c[452]||=a(`strong`,null,`Monica Geller:`,-1),c[453]||=i(` Oh-ho-ho, sweetie, sweetie, you gotta stop saying that, now. It’s no big deal, it’s not even worth mentioning, you see we all do it all the time. See watch this, Ben, Ben, Ben. (goes over and starts hitting her head on the post) Ow, Monica bang! (does it again) Everybody bang. (repeats) Ben bang. (repeats) Rachel bang. (repeats) Bang, Rachel bang! Oh, isn’t that fun?`,-1),c[454]||=a(`blockquote`,null,[a(`p`,null,`哦，呵呵，亲爱的，亲爱的，你现在不要再说了。这没什么大不了的，一点也不值得一提，你看，我们一直都这么做。看这个，本，本，本。（走过去，头撞在柱子上）噢，莫妮卡，砰！（再做一次）大家都砰的一声。（重复）本邦。（重复）瑞秋·邦。（重复）砰，瑞秋砰！哦，那不是很有趣吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/112.mp3`}),c[455]||=i(),c[456]||=a(`strong`,null,`Rachel Green:`,-1),c[457]||=i(` (goes over and hits her head on the post) Look at that! (repeats) Look at that! (repeats) We all do it. (repeats) Okay, I’m stopping now.`,-1),c[458]||=a(`blockquote`,null,[a(`p`,null,`（走过去，头撞在柱子上）看那个！（重复）看那个！（重复）我们都这样做。（重复）好了，我现在停下来。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/113.mp3`}),c[459]||=i(),c[460]||=a(`strong`,null,`Monica Geller:`,-1),c[461]||=i(` You okay?`,-1),c[462]||=a(`blockquote`,null,[a(`p`,null,`你还好吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/114.mp3`}),c[463]||=i(),c[464]||=a(`strong`,null,`Rachel Green:`,-1),c[465]||=i(` Oh yeah! Y'know, if it’s not a headboard, it’s just not worth it.`,-1),c[466]||=a(`blockquote`,null,[a(`p`,null,`哦，是的！你知道，如果不是床头板，那就不值得了。`)],-1),c[467]||=a(`hr`,null,null,-1),c[468]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's, Chandler is waiting for Janice to arrive, and is angrily fllipping through a magazine.`)],-1),c[469]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊家，钱德勒在等贾妮丝来，愤怒地翻阅杂志。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/115.mp3`}),c[470]||=i(),c[471]||=a(`strong`,null,`Janice:`,-1),c[472]||=i(` (entering) How’s my Bing-a-ling?`,-1),c[473]||=a(`blockquote`,null,[a(`p`,null,`（进来）我的冰凌怎么样？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/116.mp3`}),c[474]||=i(),c[475]||=a(`strong`,null,`Chandler Bing:`,-1),c[476]||=i(` Ah, I don’t know, you tell me. Anything you ah, wanna tell me, because, if you ah, you should, if you, you would, tell me.`,-1),c[477]||=a(`blockquote`,null,[a(`p`,null,`啊，我不知道，你告诉我。任何你想告诉我的事，因为，如果你，你应该，如果你，你会，告诉我。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/117.mp3`}),c[478]||=i(),c[479]||=a(`strong`,null,`Janice:`,-1),c[480]||=i(` Why are your eyes so white?`,-1),c[481]||=a(`blockquote`,null,[a(`p`,null,`为什么你的眼睛这么白？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/118.mp3`}),c[482]||=i(),c[483]||=a(`strong`,null,`Chandler Bing:`,-1),c[484]||=i(` You tell me! Maybe, it’s because I was just fooling with my ex! Oh no-no-no-no, no-no-no-no, that was you!!`,-1),c[485]||=a(`blockquote`,null,[a(`p`,null,`你告诉我！也许，那是因为我只是在愚弄我的前男友！哦，不，不，不，不，那是你！！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/119.mp3`}),c[486]||=i(),c[487]||=a(`strong`,null,`Janice:`,-1),c[488]||=i(` Oh my God!!`,-1),c[489]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天哪！！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/120.mp3`}),c[490]||=i(),c[491]||=a(`strong`,null,`Chandler Bing:`,-1),c[492]||=i(` All right!`,-1),c[493]||=a(`blockquote`,null,[a(`p`,null,`好吧！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/121.mp3`}),c[494]||=i(),c[495]||=a(`strong`,null,`Janice:`,-1),c[496]||=i(` How did you know?`,-1),c[497]||=a(`blockquote`,null,[a(`p`,null,`你怎么知道的？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/122.mp3`}),c[498]||=i(),c[499]||=a(`strong`,null,`Chandler Bing:`,-1),c[500]||=i(` Joey told me, he saw you two kissing.`,-1),c[501]||=a(`blockquote`,null,[a(`p`,null,`乔伊告诉我，他看见你们两个在接吻。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/123.mp3`}),c[502]||=i(),c[503]||=a(`strong`,null,`Janice:`,-1),c[504]||=i(` In the park?`,-1),c[505]||=a(`blockquote`,null,[a(`p`,null,`在公园里？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/124.mp3`}),c[506]||=i(),c[507]||=a(`strong`,null,`Chandler Bing:`,-1),c[508]||=i(` No! In his office! How many kisses were there?`,-1),c[509]||=a(`blockquote`,null,[a(`p`,null,`不！在他的办公室里！有多少个吻？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/125.mp3`}),c[510]||=i(),c[511]||=a(`strong`,null,`Janice:`,-1),c[512]||=i(` Just those two!`,-1),c[513]||=a(`blockquote`,null,[a(`p`,null,`就是那两个！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/126.mp3`}),c[514]||=i(),c[515]||=a(`strong`,null,`Chandler Bing:`,-1),c[516]||=i(` Wh-wh-why, wh-why, why, why was there kissing!? There should be no kissing!!`,-1),c[517]||=a(`blockquote`,null,[a(`p`,null,`为什么，为什么，为什么，为什么要接吻！？不应该接吻！！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/127.mp3`}),c[518]||=i(),c[519]||=a(`strong`,null,`Janice:`,-1),c[520]||=i(` Oh, I’m sorry honey, I’m so, so, (nasally) haaaaa! I’m so, so sorry, I just (nasally) haaaaaa! But I, oh what happened was, I-I-I can’t breathe. Can you get me a bag, or something?`,-1),c[521]||=a(`blockquote`,null,[a(`p`,null,`哦，对不起，亲爱的，我真的，真的，（鼻涕）哈aa！我非常非常抱歉，我只是（鼻涕地）哈哈哈！但我，发生的事是，我，我，我不能呼吸。你能给我拿个包什么的吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/128.mp3`}),c[522]||=i(),c[523]||=a(`strong`,null,`Chandler Bing:`,-1),c[524]||=i(` (giving her a bag) Here.`,-1),c[525]||=a(`blockquote`,null,[a(`p`,null,`（给她一个包）这里。`)],-1),c[526]||=a(`p`,null,[a(`em`,null,`(Janice starts to breath into it and sucks in the reciept, and then spits it out.)`)],-1),c[527]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（珍妮丝开始往里面吸气，吸进接收器，然后吐出来。）`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/129.mp3`}),c[528]||=i(),c[529]||=a(`strong`,null,`Janice:`,-1),c[530]||=i(` The receipt.`,-1),c[531]||=a(`blockquote`,null,[a(`p`,null,`收据。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/130.mp3`}),c[532]||=i(),c[533]||=a(`strong`,null,`Chandler Bing:`,-1),c[534]||=i(` I’ll take it! All right look, I gotta know. Are you finished with me? (Janice shakes her head no) Are you finished with him? (Janice shakes her head no) Do you still love him? (Janice shakes her head yes) Do you still love me? (Janice shakes her head yes) All right look, (grabs the bag) I’m gonna need an actual answer here okay, so which is it, him or me? (his phone starts to ring)`,-1),c[535]||=a(`blockquote`,null,[a(`p`,null,`我要了！好吧，听着，我得知道。你跟我说完了吗？（珍妮丝摇摇头不）你和他完了吗？（珍妮丝摇摇头不）你还爱他吗？（珍妮丝摇摇头是的）你还爱我吗？（珍妮丝摇摇头是的）好吧，听着，（抓起袋子）我需要一个真实的答案好吧，那是他还是我？（他的电话响了起来）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/131.mp3`}),c[536]||=i(),c[537]||=a(`strong`,null,`Janice:`,-1),c[538]||=i(` I don’t know.`,-1),c[539]||=a(`blockquote`,null,[a(`p`,null,`我不知道。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/132.mp3`}),c[540]||=t(` <strong>Phoebe Buffay:</strong> (rushing in) Okay. If you’re alive you answer your phone!<blockquote><p>（冲进来）好的。如果你还活着，你就接电话！</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Monica, Rachel, Phoebe, and Joey are there.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，莫妮卡，瑞秋，菲比和乔伊在那里</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S03/S03E08/133.mp3`}),c[541]||=i(),c[542]||=a(`strong`,null,`Monica Geller:`,-1),c[543]||=i(` Okay, Ben, I won’t tell your daddy that you had ice cream for dinner, if you don’t tell about our little bonking incident.`,-1),c[544]||=a(`blockquote`,null,[a(`p`,null,`好吧，本，如果你不告诉我我们的小撞车事件，我就不会告诉你爸爸你晚餐吃了冰淇淋。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/134.mp3`}),c[545]||=i(),c[546]||=a(`strong`,null,`Rachel Green:`,-1),c[547]||=i(` Monica, number one, I don’t think Ben understands the concept of bribery, and number two, I... (Joey starts laughing in the background) (to Joey) What?!`,-1),c[548]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡，第一，我认为本不理解贿赂的概念，第二，我。。。（乔伊开始在后台笑）（对乔伊）什么？！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/135.mp3`}),c[549]||=i(),c[550]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[551]||=i(` You said number two.`,-1),c[552]||=a(`blockquote`,null,[a(`p`,null,`你说的是二号。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/136.mp3`}),c[553]||=i(),c[554]||=a(`strong`,null,`Rachel Green:`,-1),c[555]||=i(` I also said number one.`,-1),c[556]||=a(`blockquote`,null,[a(`p`,null,`我也说了第一。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/137.mp3`}),c[557]||=i(),c[558]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[559]||=i(` I know. (giggles harder)`,-1),c[560]||=a(`blockquote`,null,[a(`p`,null,`我知道。（咯咯地笑）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/138.mp3`}),c[561]||=i(),c[562]||=a(`strong`,null,`Ross Geller:`,-1),c[563]||=i(` (entering) Hey! Everyone.`,-1),c[564]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！每个人`)],-1),r(p,{src:`/audio/friends/S03/S03E08/139.mp3`}),c[565]||=i(),c[566]||=a(`strong`,null,`Rachel Green:`,-1),c[567]||=i(` Hi!`,-1),c[568]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/140.mp3`}),c[569]||=i(),c[570]||=a(`strong`,null,`Ross Geller:`,-1),c[571]||=i(` How’s my little boy?`,-1),c[572]||=a(`blockquote`,null,[a(`p`,null,`我的小男孩怎么样？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/141.mp3`}),c[573]||=i(),c[574]||=a(`strong`,null,`Rachel Green:`,-1),c[575]||=i(` He’s perfect, he’s never been better.`,-1),c[576]||=a(`blockquote`,null,[a(`p`,null,`他很完美，从来没有比现在更好过。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/142.mp3`}),c[577]||=i(),c[578]||=a(`strong`,null,`Ross Geller:`,-1),c[579]||=i(` (noticing the outfit he is wearing) What’d you do, take him whaling?`,-1),c[580]||=a(`blockquote`,null,[a(`p`,null,`（注意到他穿着的衣服）你做了什么，带他去捕鲸？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/143.mp3`}),c[581]||=i(),c[582]||=a(`strong`,null,`Ben:`,-1),c[583]||=i(` Monica.`,-1),c[584]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/144.mp3`}),c[585]||=i(),c[586]||=a(`strong`,null,`Ross Geller:`,-1),c[587]||=i(` Oh my God, he just said your name, that’s great! Good job Ben.`,-1),c[588]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，他刚说了你的名字，太好了！干得好，本。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/145.mp3`}),c[589]||=i(),c[590]||=a(`strong`,null,`Ben:`,-1),c[591]||=i(` Monica bang!`,-1),c[592]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡·邦！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/146.mp3`}),c[593]||=i(),c[594]||=a(`strong`,null,`Monica Geller:`,-1),c[595]||=i(` Oh that’s right, that’s what I’d sound like if I exploded.`,-1),c[596]||=a(`blockquote`,null,[a(`p`,null,`哦，对了，如果我爆炸了，我听起来就是这样。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/147.mp3`}),c[597]||=i(),c[598]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[599]||=i(` Woo-Hoo! The curse is broken! I called everybody I know, and everyone is alive.`,-1),c[600]||=a(`blockquote`,null,[a(`p`,null,`呜呜呜！诅咒解除了！我打电话给我认识的每个人，每个人都还活着。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/148.mp3`}),c[601]||=i(),c[602]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[603]||=i(` Uh.`,-1),c[604]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/149.mp3`}),c[605]||=i(),c[606]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[607]||=i(` What?`,-1),c[608]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/150.mp3`}),c[609]||=i(),c[610]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[611]||=i(` Ugly Naked Guy looks awfully still. (Phoebe runs to the window and gasps.)`,-1),c[612]||=a(`blockquote`,null,[a(`p`,null,`丑陋的裸男看起来非常安静。（菲比跑到窗前喘着粗气。）`)],-1),c[613]||=a(`p`,null,`[Cut to later, all except Chandler are staring out the window at Ugly Naked Guy.]`,-1),c[614]||=a(`blockquote`,null,[a(`p`,null,`[切换到稍后，除了钱德勒，所有人都盯着窗外丑陋的裸男。]`)],-1),r(p,{src:`/audio/friends/S03/S03E08/151.mp3`}),c[615]||=i(),c[616]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[617]||=i(` Oh my God! I killed him! I killed another one! And this curse is getting stronger too, to bring down something that big.`,-1),c[618]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！我杀了他！我又杀了一个！而且这种诅咒也越来越强烈，要摧毁这么大的东西。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/152.mp3`}),c[619]||=i(),c[620]||=a(`strong`,null,`Rachel Green:`,-1),c[621]||=i(` Well maybe he’s just taking a nap.`,-1),c[622]||=a(`blockquote`,null,[a(`p`,null,`也许他只是在小睡一会儿。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/153.mp3`}),c[623]||=i(),c[624]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[625]||=i(` I’m tellin’ ya, he hasn’t moved since this morning.`,-1),c[626]||=a(`blockquote`,null,[a(`p`,null,`我告诉你，他从今天早上就没动过。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/154.mp3`}),c[627]||=i(),c[628]||=a(`strong`,null,`Monica Geller:`,-1),c[629]||=i(` All right, we should call somebody.`,-1),c[630]||=a(`blockquote`,null,[a(`p`,null,`好吧，我们应该找个人。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/155.mp3`}),c[631]||=i(),c[632]||=a(`strong`,null,`Ross Geller:`,-1),c[633]||=i(` And tell them what? The naked guy we stare at all the time isn’t moving.`,-1),c[634]||=a(`blockquote`,null,[a(`p`,null,`告诉他们什么？我们一直盯着的裸体男人一动不动。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/156.mp3`}),c[635]||=i(),c[636]||=a(`strong`,null,`Rachel Green:`,-1),c[637]||=i(` Well, we have gotta find out if he’s alive.`,-1),c[638]||=a(`blockquote`,null,[a(`p`,null,`嗯，我们得弄清楚他是否还活着。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/157.mp3`}),c[639]||=i(),c[640]||=a(`strong`,null,`Monica Geller:`,-1),c[641]||=i(` How are we gonna do that? There’s no way.`,-1),c[642]||=a(`blockquote`,null,[a(`p`,null,`我们怎么做？不可能。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/158.mp3`}),c[643]||=i(),c[644]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[645]||=i(` Well, there is one way. His window’s open, I say, we poke him.`,-1),c[646]||=a(`blockquote`,null,[a(`p`,null,`嗯，有一种方法。他的窗户开着，我说，我们戳他。`)],-1),c[647]||=a(`hr`,null,null,-1),c[648]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's, Chandler is throwing darts, as Joey enters.`)],-1),c[649]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊家，乔伊进来时，钱德勒正在投掷飞镖。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/159.mp3`}),c[650]||=i(),c[651]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[652]||=i(` Hey! Y'know how we ah, save all those chopsticks for no reason we get when we get Chinese food?`,-1),c[653]||=a(`blockquote`,null,[a(`p`,null,`嘿！你知道我们是怎么啊，当我们吃中国菜的时候，把所有的筷子都省下来，没有理由吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/160.mp3`}),c[654]||=i(),c[655]||=a(`strong`,null,`Chandler Bing:`,-1),c[656]||=i(` Yeah.`,-1),c[657]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/161.mp3`}),c[658]||=i(),c[659]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[660]||=i(` Well, now we got a reason.`,-1),c[661]||=a(`blockquote`,null,[a(`p`,null,`好吧，现在我们有理由了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/162.mp3`}),c[662]||=i(),c[663]||=a(`strong`,null,`Chandler Bing:`,-1),c[664]||=i(` What?`,-1),c[665]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/163.mp3`}),c[666]||=i(),c[667]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[668]||=i(` Well, we’re fashioning a very long poking device.`,-1),c[669]||=a(`blockquote`,null,[a(`p`,null,`嗯，我们正在制作一种很长的戳器。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/164.mp3`}),c[670]||=i(),c[671]||=a(`strong`,null,`Chandler Bing:`,-1),c[672]||=i(` All right.`,-1),c[673]||=a(`blockquote`,null,[a(`p`,null,`好吧。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/165.mp3`}),c[674]||=i(),c[675]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[676]||=i(` Hey uh, what’s a matter?`,-1),c[677]||=a(`blockquote`,null,[a(`p`,null,`嘿，呃，怎么了？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/166.mp3`}),c[678]||=i(),c[679]||=a(`strong`,null,`Chandler Bing:`,-1),c[680]||=i(` I talked to Janice.`,-1),c[681]||=a(`blockquote`,null,[a(`p`,null,`我和珍妮丝谈过了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/167.mp3`}),c[682]||=i(),c[683]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[684]||=i(` Oh my God, is she going back to him?`,-1),c[685]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，她会回到他身边吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/168.mp3`}),c[686]||=i(),c[687]||=a(`strong`,null,`Chandler Bing:`,-1),c[688]||=i(` She doesn’t know. Says she loves us both. Y'know I woke up this morning and I was in love, well I was happy. Y'know it serves me right for buying that twelve pack of condoms. And now I can’t even return them, because she choked on the reciept!`,-1),c[689]||=a(`blockquote`,null,[a(`p`,null,`她不知道。她说她爱我们俩。你知道我今天早上醒来，我爱上了她，我很开心。你知道我买了那12包安全套是对的。现在我甚至不能把它们还给她，因为她被收据噎住了！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/169.mp3`}),c[690]||=i(),c[691]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[692]||=i(` What are you ah, what are you gonna do?`,-1),c[693]||=a(`blockquote`,null,[a(`p`,null,`你在干什么啊，你打算干什么？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/170.mp3`}),c[694]||=i(),c[695]||=a(`strong`,null,`Chandler Bing:`,-1),c[696]||=i(` I don’t know, y'know. What, what, would you do?`,-1),c[697]||=a(`blockquote`,null,[a(`p`,null,`我不知道，你知道。你会怎么做？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/171.mp3`}),c[698]||=i(),c[699]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[700]||=i(` Well, it doesn’t matter what I would do.`,-1),c[701]||=a(`blockquote`,null,[a(`p`,null,`嗯，我会怎么做都没关系。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/172.mp3`}),c[702]||=i(),c[703]||=a(`strong`,null,`Chandler Bing:`,-1),c[704]||=i(` Come on, tell me.`,-1),c[705]||=a(`blockquote`,null,[a(`p`,null,`来吧，告诉我。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/173.mp3`}),c[706]||=i(),c[707]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[708]||=i(` All right, you’re probably not gonna want to hear this but ah, if it was me, and this is just me, (Chandler gets ready to throw another dart) I would ah, I would bow out.`,-1),c[709]||=a(`blockquote`,null,[a(`p`,null,`好吧，你可能不想听这个，但是啊，如果是我，而这只是我，（钱德勒准备再投一支飞镖）我会啊，我会退出。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/174.mp3`}),c[710]||=i(),c[711]||=a(`strong`,null,`Chandler Bing:`,-1),c[712]||=i(` What? (turns around quickly still ready to throw the dart and Joey quickly ducks and hides behind the chair) What are you, what are you talking about?`,-1),c[713]||=a(`blockquote`,null,[a(`p`,null,`什么？（迅速转过身准备掷飞镖，乔伊迅速躲到椅子后面）你在说什么，你在说什么？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/175.mp3`}),c[714]||=i(),c[715]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[716]||=i(` They have a kid together, y'know. They’re like, they’re like a family, and if, I don’t know, there’s chance they could make that work, I know I wouldn’t want to be the guy who stood in the way of that. Are you okay? Do you wanna ah, come poke a nude guy?`,-1),c[717]||=a(`blockquote`,null,[a(`p`,null,`他们有个孩子在一起，你知道。他们就像，他们就像一个家庭，如果，我不知道，他们有机会做到这一点，我知道我不想成为阻碍这一点的人。你没事吧？你想啊，来捅一个裸体男人吗？`)],-1),c[718]||=a(`hr`,null,null,-1),c[719]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Ross has just finished putting Ben to sleep, and is entering from Rachel’s room.`)],-1),c[720]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，罗斯刚刚让本入睡，从瑞秋的房间走了进来。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/176.mp3`}),c[721]||=i(),c[722]||=a(`strong`,null,`Ross Geller:`,-1),c[723]||=i(` Well, he’s finally alseep. About that ah, bump on his head?`,-1),c[724]||=a(`blockquote`,null,[a(`p`,null,`嗯，他终于睡着了。关于这个啊,撞到他头上?？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/177.mp3`}),c[725]||=i(),c[726]||=a(`strong`,null,`Rachel Green:`,-1),c[727]||=i(` Are you, are you, are you sure it’s ah, a new bump? I mean, no offense, I’ve always thought of Ben as a fairly bumpy headed child.`,-1),c[728]||=a(`blockquote`,null,[a(`p`,null,`你，你，你确定这是新的肿块吗？我是说，无意冒犯，我一直认为本是个相当笨的孩子。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/178.mp3`}),c[729]||=i(),c[730]||=a(`strong`,null,`Ross Geller:`,-1),c[731]||=i(` It’s okay if he bumps his head, kids bump their heads all the time, y'know, it was your first time babysitting, I figured you did the best you could.`,-1),c[732]||=a(`blockquote`,null,[a(`p`,null,`如果他撞到他的头，孩子们总是撞到他们的头，没关系，你知道，这是你第一次当保姆，我想你已经尽力了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/179.mp3`}),c[733]||=i(),c[734]||=a(`strong`,null,`Rachel Green:`,-1),c[735]||=i(` (confidently) I did!`,-1),c[736]||=a(`blockquote`,null,[a(`p`,null,`（自信地）是的！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/180.mp3`}),c[737]||=i(),c[738]||=a(`strong`,null,`Ross Geller:`,-1),c[739]||=i(` I know! I’m saying you have to watch them all the time.`,-1),c[740]||=a(`blockquote`,null,[a(`p`,null,`我知道！我是说你必须一直看着他们。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/181.mp3`}),c[741]||=i(),c[742]||=a(`strong`,null,`Rachel Green:`,-1),c[743]||=i(` I did!! I watched! I watched! I watched Monica bang his head against that thing!`,-1),c[744]||=a(`blockquote`,null,[a(`p`,null,`是的！！我看了！我看了！我看着莫妮卡用头撞那东西！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/182.mp3`}),c[745]||=i(),c[746]||=a(`strong`,null,`Ross Geller:`,-1),c[747]||=i(` Monica did it?`,-1),c[748]||=a(`blockquote`,null,[a(`p`,null,`是莫妮卡干的？`)],-1),c[749]||=a(`p`,null,[a(`em`,null,`(Monica runs into the kitchen from the terrace.)`)],-1),c[750]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡从阳台跑进厨房。）`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/183.mp3`}),c[751]||=i(),c[752]||=a(`strong`,null,`Ross Geller:`,-1),c[753]||=i(` Monica?`,-1),c[754]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/184.mp3`}),c[755]||=i(),c[756]||=a(`strong`,null,`Monica Geller:`,-1),c[757]||=i(` Yeah.`,-1),c[758]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/185.mp3`}),c[759]||=i(),c[760]||=a(`strong`,null,`Ross Geller:`,-1),c[761]||=i(` Umm, did you notice anything wierd about Ben today?`,-1),c[762]||=a(`blockquote`,null,[a(`p`,null,`嗯，你注意到本今天有什么奇怪的事吗？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/186.mp3`}),c[763]||=i(),c[764]||=a(`strong`,null,`Monica Geller:`,-1),c[765]||=i(` No. Why?`,-1),c[766]||=a(`blockquote`,null,[a(`p`,null,`没有，为什么？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/187.mp3`}),c[767]||=i(),c[768]||=a(`strong`,null,`Ross Geller:`,-1),c[769]||=i(` Well, I was just playing with him, and y'know we were doing the alphabet song, which he used to be really good at, but suddenly he’s leaving out ‘e’ and ‘f.’ It’s like they just ah, I don’t know, fell out of his head.`,-1),c[770]||=a(`blockquote`,null,[a(`p`,null,`嗯，我只是和他一起玩，你知道我们在唱字母歌，他以前很擅长，但突然他忘了“e”和“f”。好像他们只是啊，我不知道，从他的脑子里掉出来了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/188.mp3`}),c[771]||=i(),c[772]||=a(`strong`,null,`Monica Geller:`,-1),c[773]||=i(` Really?!`,-1),c[774]||=a(`blockquote`,null,[a(`p`,null,`真的吗？！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/189.mp3`}),c[775]||=i(),c[776]||=a(`strong`,null,`Ross Geller:`,-1),c[777]||=i(` Oh, and also, he’s, he’s walkin’ kind of funny, his left leg is moving a lot faster than his right leg, and he’s in there just sort of y'know... (walks around in a circle)`,-1),c[778]||=a(`blockquote`,null,[a(`p`,null,`哦，还有，他，他走路有点滑稽，他的左腿比右腿移动得快，他就在那里，你知道。。。（绕着一圈走）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/190.mp3`}),c[779]||=i(),c[780]||=a(`strong`,null,`Monica Geller:`,-1),c[781]||=i(` Oh my God, I wrecked your baby!! (runs into the bedroom)`,-1),c[782]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，我把你的孩子弄坏了！！（跑进卧室）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/191.mp3`}),c[783]||=i(),c[784]||=a(`strong`,null,`Rachel Green:`,-1),c[785]||=i(` I hope it’s still funny when you’re in hell.`,-1),c[786]||=a(`blockquote`,null,[a(`p`,null,`我希望你在地狱的时候仍然很有趣。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/192.mp3`}),c[787]||=i(),c[788]||=a(`strong`,null,`Monica Geller:`,-1),c[789]||=i(` (coming out of the bedroom) You jerk! You know how much I love that kid! (starts to chase Ross around the living room)`,-1),c[790]||=a(`blockquote`,null,[a(`p`,null,`（走出卧室）你这个混蛋！你知道我有多爱那孩子！（开始在客厅里追罗斯）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/193.mp3`}),c[791]||=i(),c[792]||=a(`strong`,null,`Ross Geller:`,-1),c[793]||=i(` Monica bang! Monica bang! (runs into one of the posts) Ow!`,-1),c[794]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡·邦！莫妮卡·邦！（跑进一根柱子）哇！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/194.mp3`}),c[795]||=i(),c[796]||=a(`strong`,null,`Rachel Green:`,-1),c[797]||=i(` I’ll get the hat.`,-1),c[798]||=a(`blockquote`,null,[a(`p`,null,`我去拿帽子。`)],-1),c[799]||=a(`hr`,null,null,-1),c[800]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Chandler and Janice are there.`)],-1),c[801]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，钱德勒和珍妮丝在那里`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/195.mp3`}),c[802]||=i(),c[803]||=a(`strong`,null,`Chandler Bing:`,-1),c[804]||=i(` Janice, I have something I need to tell you, and I want you to let me get through it, because it’s, it’s, it’s not gonna be easy.`,-1),c[805]||=a(`blockquote`,null,[a(`p`,null,`珍妮丝，我有件事要告诉你，我希望你能让我度过难关，因为这不容易。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/196.mp3`}),c[806]||=i(),c[807]||=a(`strong`,null,`Janice:`,-1),c[808]||=i(` Okay.`,-1),c[809]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/197.mp3`}),c[810]||=i(),c[811]||=a(`strong`,null,`Chandler Bing:`,-1),c[812]||=i(` I think you should go back with Gary. I don’t wanna be the guy that breaks up a family, y'know when my parents split up, it was because of that guy. Whenever I would see him I was always think y'know ‘You’re the reason, you are the reason why their not together.’ and I hated that guy. And it didn’t matter how nice he was, or how happy he made my Dad.`,-1),c[813]||=a(`blockquote`,null,[a(`p`,null,`我想你应该和加里一起回去。我不想成为那种拆散家庭的人，你知道当我父母分手的时候，都是因为那个人。每当我见到他，我总是觉得你是他们不在一起的原因，你是他们不在一起的原因。我恨那个家伙。不管他有多好，也不管他让我爸爸有多开心。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/198.mp3`}),c[814]||=i(),c[815]||=a(`strong`,null,`Janice:`,-1),c[816]||=i(` Wow!`,-1),c[817]||=a(`blockquote`,null,[a(`p`,null,`哇！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/199.mp3`}),c[818]||=i(),c[819]||=a(`strong`,null,`Chandler Bing:`,-1),c[820]||=i(` Yeah, well. It’s the right thing to do.`,-1),c[821]||=a(`blockquote`,null,[a(`p`,null,`是的，嗯。这是正确的做法。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/200.mp3`}),c[822]||=i(),c[823]||=a(`strong`,null,`Janice:`,-1),c[824]||=i(` Oh! You’re right. Oh God. But, before I can say ‘good-bye’, there’s something I really need you to know, Chandler. The way I feel about you, it’s like, I finally understand what Lionel Richie’s been singing about. Y'know, I mean what we have, it’s like movie love, you’re my soulmate, and I can’t believe we’re not going to be spending the rest of our lives together.`,-1),c[825]||=a(`blockquote`,null,[a(`p`,null,`哦！你说得对。哦，上帝。但是，在我说“再见”之前，有件事我真的需要你知道，钱德勒。我对你的感觉是，我终于明白莱昂内尔·里奇在唱什么了。你知道，我是说我们拥有的，就像电影《爱情》，你是我的灵魂伴侣，我不敢相信我们不会在一起度过余生。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/201.mp3`}),c[826]||=i(),c[827]||=a(`strong`,null,`Chandler Bing:`,-1),c[828]||=i(` Then don’t leave me!`,-1),c[829]||=a(`blockquote`,null,[a(`p`,null,`那就别离开我！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/202.mp3`}),c[830]||=i(),c[831]||=a(`strong`,null,`Janice:`,-1),c[832]||=i(` What?`,-1),c[833]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S03/S03E08/203.mp3`}),c[834]||=i(),c[835]||=a(`strong`,null,`Chandler Bing:`,-1),c[836]||=i(` Forget what I said, I was babbling! Pick me!`,-1),c[837]||=a(`blockquote`,null,[a(`p`,null,`忘了我说的吧，我在胡说！选我！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/204.mp3`}),c[838]||=i(),c[839]||=a(`strong`,null,`Janice:`,-1),c[840]||=i(` No, you were right, you were right. I mean, I-I-I’ve got to give my marriage another chance.`,-1),c[841]||=a(`blockquote`,null,[a(`p`,null,`不，你是对的，你是对的。我是说，我得再给我的婚姻一次机会。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/205.mp3`}),c[842]||=i(),c[843]||=a(`strong`,null,`Chandler Bing:`,-1),c[844]||=i(` No you don’t! No, no, no, I say you have to give your divorce another chance.`,-1),c[845]||=a(`blockquote`,null,[a(`p`,null,`不，你没有！不，不，不，我说你得再给你一次离婚的机会。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/206.mp3`}),c[846]||=i(),c[847]||=a(`strong`,null,`Janice:`,-1),c[848]||=i(` (standing up) I’m sorry. (hugs him)`,-1),c[849]||=a(`blockquote`,null,[a(`p`,null,`（站起来）对不起。（拥抱他）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/207.mp3`}),c[850]||=i(),c[851]||=a(`strong`,null,`Chandler Bing:`,-1),c[852]||=i(` Ohhh. Don’t go.`,-1),c[853]||=a(`blockquote`,null,[a(`p`,null,`哦。别走。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/208.mp3`}),c[854]||=i(),c[855]||=a(`strong`,null,`Janice:`,-1),c[856]||=i(` No, I-I-I gotta go. (she starts to walk away, but Chandler doesn’t let her go.)`,-1),c[857]||=a(`blockquote`,null,[a(`p`,null,`不，我得走了。（她开始走开，但钱德勒没有让她走。）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/209.mp3`}),c[858]||=i(),c[859]||=a(`strong`,null,`Chandler Bing:`,-1),c[860]||=i(` No. No! No! No!`,-1),c[861]||=a(`blockquote`,null,[a(`p`,null,`不，不！不不`)],-1),r(p,{src:`/audio/friends/S03/S03E08/210.mp3`}),c[862]||=i(),c[863]||=a(`strong`,null,`Janice:`,-1),c[864]||=i(` Honey, honey, people are looking.`,-1),c[865]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，亲爱的，人们都在看。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/211.mp3`}),c[866]||=i(),c[867]||=a(`strong`,null,`Chandler Bing:`,-1),c[868]||=i(` I don’t care! (turns around and to the people watching them) I don’t care!!`,-1),c[869]||=a(`blockquote`,null,[a(`p`,null,`我不在乎！（转过身，对着看着他们的人）我不在乎！！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/212.mp3`}),c[870]||=i(),c[871]||=a(`strong`,null,`Janice:`,-1),c[872]||=i(` Yeah, um, I’m, I’m leaving now. (tries to get her leg out of Chandler’s grasp, she finally does, but Chandler takes off her shoe.)`,-1),c[873]||=a(`blockquote`,null,[a(`p`,null,`是的，嗯，我现在要走了。（她试图把腿从钱德勒的手上拿开，但钱德勒脱下了鞋子。）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/213.mp3`}),c[874]||=i(),c[875]||=a(`strong`,null,`Chandler Bing:`,-1),c[876]||=i(` You can’t leave! I have your shoe!`,-1),c[877]||=a(`blockquote`,null,[a(`p`,null,`你不能走！我有你的鞋！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/214.mp3`}),c[878]||=i(),c[879]||=a(`strong`,null,`Janice:`,-1),c[880]||=i(` Good-bye Chandler Bing. (walks out with one shoe)`,-1),c[881]||=a(`blockquote`,null,[a(`p`,null,`再见，钱德勒·宾。（带着一只鞋走了出去）`)],-1),r(p,{src:`/audio/friends/S03/S03E08/215.mp3`}),c[882]||=i(),c[883]||=a(`strong`,null,`Gunther:`,-1),c[884]||=i(` Rachel has those in burgendy.`,-1),c[885]||=a(`blockquote`,null,[a(`p`,null,`瑞秋在勃艮第有。`)],-1),c[886]||=a(`hr`,null,null,-1),c[887]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Joey, Rachel, Monica, Phoebe, and Ross are holding the giant poking device.`)],-1),c[888]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋的，乔伊，瑞秋，莫妮卡，菲比和罗斯拿着这个巨大的戳器。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/216.mp3`}),c[889]||=i(),c[890]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[891]||=i(` All right now remember, something this big and long is going to be difficult to manuver, fortunately I have a lot of experience in that area.`,-1),c[892]||=a(`blockquote`,null,[a(`p`,null,`好吧，记住，这么长这么大的东西很难制作，幸运的是我在这方面有很多经验。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/217.mp3`}),c[893]||=i(),c[894]||=a(`strong`,null,`Ross Geller:`,-1),c[895]||=i(` Can we please focus here, a naked man’s life hangs in the balance!`,-1),c[896]||=a(`blockquote`,null,[a(`p`,null,`我们能不能集中注意力，一个裸体男人的生命悬在天平上！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/218.mp3`}),c[897]||=i(),c[898]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[899]||=i(` I’m telling you he’s dead. What we are about to have here is a dead fat guy on a stick.`,-1),c[900]||=a(`blockquote`,null,[a(`p`,null,`我告诉你他死了。我们将看到一个死胖子站在木棍上。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/219.mp3`}),c[901]||=i(),c[902]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[903]||=i(` All right, ladies and gentlemen, let’s poke. (they start to advance the giant poking device) Steady. Steady. Okay, a little higher. Careful of the angle. Okay, okay, we’re approaching the window (as he says this the camera cuts to their view of Ugly Naked Guy, so that we actually see him!) Thread the needle. Thread the needle.`,-1),c[904]||=a(`blockquote`,null,[a(`p`,null,`好了，女士们，先生们，我们来戳戳。（他们开始推进巨大的拨动装置）稳定。稳定。好的，再高一点。小心角度。好了，好了，我们正在接近窗户（当他说这句话时，摄像机切到了他们看到的丑陋裸男的视角，这样我们就能看到他了！）穿针。穿线。`)],-1),c[905]||=a(`p`,null,[a(`em`,null,`(They thread the needle and start poking him, he then stirs.)`)],-1),c[906]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们穿针开始戳他，然后他搅拌。）`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/220.mp3`}),c[907]||=i(),c[908]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[909]||=i(` He’s alive! He’s a-live!!!`,-1),c[910]||=a(`blockquote`,null,[a(`p`,null,`他还活着！他是个活人！！！`)],-1),r(p,{src:`/audio/friends/S03/S03E08/221.mp3`}),c[911]||=i(),c[912]||=a(`strong`,null,`Monica Geller:`,-1),c[913]||=i(` And yet, we’re still poking him.`,-1),c[914]||=a(`blockquote`,null,[a(`p`,null,`但我们还是在戳他。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/222.mp3`}),c[915]||=i(),c[916]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[917]||=i(` Okay, retract the device, retract the device.`,-1),c[918]||=a(`blockquote`,null,[a(`p`,null,`好的，收回设备，收回设备。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/223.mp3`}),c[919]||=i(),c[920]||=a(`strong`,null,`Ross Geller:`,-1),c[921]||=i(` He does not look happy.`,-1),c[922]||=a(`blockquote`,null,[a(`p`,null,`他看起来不高兴。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/224.mp3`}),c[923]||=i(),c[924]||=a(`strong`,null,`Rachel Green:`,-1),c[925]||=i(` Hey-hey, now he’s showing us his poking device.`,-1),c[926]||=a(`blockquote`,null,[a(`p`,null,`嘿，嘿，现在他给我们看他的戳器。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/225.mp3`}),c[927]||=t(` <strong>Joey Tribbiani:</strong> Hey, that’s never gonna make it all the way over here, buddy!<blockquote><p>嘿，老兄，这一路都走不过去！</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Chandler is listening to a Lionel Richie album</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的，钱德勒正在听莱昂内尔·里奇的专辑</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S03/S03E08/226.mp3`}),c[928]||=i(),c[929]||=a(`strong`,null,`Chandler Bing:`,-1),c[930]||=i(` (singing) I’ll hold you close in my arms. (Phoebe enters) I can’t resist your charms. And love....`,-1),c[931]||=a(`blockquote`,null,[a(`p`,null,`（唱）我会把你紧紧抱在怀里。（菲比进来）我无法抗拒你的魅力。还有爱。。。。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/227.mp3`}),c[932]||=i(),c[933]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[934]||=i(` (joining him) Love....`,-1),c[935]||=a(`blockquote`,null,[a(`p`,null,`（和他一起）爱。。。。`)],-1),c[936]||=a(`p`,null,`Chandler and **Phoebe Buffay: **I’ll be a fool for you. I’m sure, you know I don’t mind.`,-1),c[937]||=a(`blockquote`,null,[a(`p`,null,[i(`钱德勒和`),a(`strong`,null,`菲比·布菲：`),i(`我会成为你的傻瓜。我肯定，你知道我不介意。`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/228.mp3`}),c[938]||=i(),c[939]||=a(`strong`,null,`Chandler Bing:`,-1),c[940]||=i(` (high pitched) No you know I don’t mind.`,-1),c[941]||=a(`blockquote`,null,[a(`p`,null,`（高音）不，你知道我不介意。`)],-1),c[942]||=a(`p`,null,`Chandler and **Phoebe Buffay: **Yes! You mean the world the world to me. Oh...`,-1),c[943]||=a(`blockquote`,null,[a(`p`,null,[i(`钱德勒和`),a(`strong`,null,`菲比·布菲：`),i(`是的！你是我的整个世界。哦`)])],-1),r(p,{src:`/audio/friends/S03/S03E08/229.mp3`}),c[944]||=i(),c[945]||=a(`strong`,null,`Chandler Bing:`,-1),c[946]||=i(` I know.`,-1),c[947]||=a(`blockquote`,null,[a(`p`,null,`我知道。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/230.mp3`}),c[948]||=i(),c[949]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[950]||=i(` I know.`,-1),c[951]||=a(`blockquote`,null,[a(`p`,null,`我知道。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/231.mp3`}),c[952]||=i(),c[953]||=a(`strong`,null,`Chandler Bing:`,-1),c[954]||=i(` I’ve found.`,-1),c[955]||=a(`blockquote`,null,[a(`p`,null,`我找到了。`)],-1),r(p,{src:`/audio/friends/S03/S03E08/232.mp3`}),c[956]||=i(),c[957]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[958]||=i(` I’ve found....`,-1),c[959]||=a(`blockquote`,null,[a(`p`,null,`我发现。。。。`)],-1),c[960]||=a(`p`,null,`Chandler and **Phoebe Buffay: **...in you, my endless (Phoebe goes high pitched, Chandler goes low pitched) love. (they both look at each other.) My endless love. (once again they don’t match tones, and they just look at each other)`,-1),c[961]||=a(`blockquote`,null,[a(`p`,null,[i(`钱德勒和`),a(`strong`,null,`菲比·布菲：`),i(`……在你身上，我无尽的爱（菲比高音，钱德勒低音）。（他们都看着对方）我无尽的爱。（再一次，他们的音调不匹配，他们只是互相看着）`)])],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};